const BRAND={app:'SaberLingo',chatPh:'ex.: o que faz a mitocôndria?',tutor:'Professora Rosalind',sym:'DNA',body:'#2bb673',dark:'#1f8f57',belly:'#dcf7e8',lsKey:'biolingo_v1',first:'vida',
 welcome:'Biologia do <b>Fundamental ao Ensino Médio</b>: célula, genética, evolução, seres vivos, corpo humano e ecologia — com cruzamentos genéticos e cálculos gerados sem parar.',
 range:'do Fundamental ao Ensino Médio (ENEM e vestibulares)',searchEx:'ex.: mitose',firstName:'Características dos seres vivos',
 chips:['O que faz a mitocôndria?','Mitose ou meiose?','Vacina e soro','1ª Lei de Mendel','Relações ecológicas','Biomas brasileiros'],
 askEx:'<i>"o que é osmose?"</i>, <i>"mitose"</i>, <i>"mutualismo"</i>',
 formulas:'cruzamentos (1ª Lei de Mendel), fotossíntese, respiração celular e pirâmides de energia'};
const UNITS=[];

/* ---------- geradores de Biologia ---------- */
const BASES='ATCG';
const COMP={A:'T',T:'A',C:'G',G:'C'},TRANS={A:'U',T:'A',C:'G',G:'C'};
const rseq=n=>[...Array(n)].map(()=>pick(BASES)).join('');
const FR={0:'0',1:'1/4',2:'1/2',3:'3/4',4:'1'};
const PCT={0:'0%',1:'25%',2:'50%',3:'75%',4:'100%'};
const TRAITS=[['ervilhas','a semente amarela (A)','a semente verde (a)'],['coelhos','a pelagem preta (A)','a pelagem branca (a)'],['humanos','a pigmentação normal (A)','o albinismo (a)'],['moscas-das-frutas','a asa longa (A)','a asa vestigial (a)'],['plantas de tomate','o caule roxo (A)','o caule verde (a)']];
function cross(p1,p2){ const off=[]; for(const a of p1) for(const b of p2) off.push([a,b].sort().join('')); return off; }
const GT={AA:'homozigoto dominante (AA)',Aa:'heterozigoto (Aa)',aa:'homozigoto recessivo (aa)'};
const bioGens={
 dna:lv=>{ let s; do{ s=rseq(lv>=3?9:6); }while(![...BASES].every(b=>s.includes(b))); const t=R(0,1);
   if(t===0){ const c=[...s].map(b=>COMP[b]).join(''); return MC(`Qual é a fita complementar do DNA <b>${s}</b>?`,c,[[...s].map(b=>TRANS[b]).join(''),s,[...c].reverse().join(''),[...s].map(b=>({A:'G',G:'A',T:'C',C:'T'})[b]).join('')],`No DNA, A pareia com T e C pareia com G: <b>${c}</b>.`,'Pareamento no DNA: A–T e C–G.'); }
   const r=[...s].map(b=>TRANS[b]).join(''); return MC(`Qual RNA mensageiro é transcrito a partir da fita molde de DNA <b>${s}</b>?`,r,[[...s].map(b=>COMP[b]).join(''),s.replace(/T/g,'U'),[...r].reverse().join('')],`Na transcrição, A → U, T → A, C → G, G → C: <b>${r}</b>. O RNA tem uracila (U) no lugar da timina.`,'No RNA não há timina: o A do DNA pareia com U.'); },
 codon:lv=>{ const k=R(4,lv>=3?120:30); return NUM(`Um RNA mensageiro tem <b>${3*k}</b> nucleotídeos codificantes (sem contar o códon de parada). Quantos aminoácidos terá a proteína?`,k,`Cada códon (trinca de bases) codifica 1 aminoácido: ${3*k} / 3 = <b>${k}</b>.`,'Cada aminoácido é codificado por 3 nucleotídeos (um códon).'); },
 mendel:lv=>{ const [org,dom,rec]=pick(TRAITS),g=['AA','Aa','aa']; let p1=pick(g),p2=pick(g); if(lv>=1&&Math.random()<.5){p1='Aa';p2=pick(['Aa','aa']);}
   const off=cross(p1,p2),t=R(0,2),n={AA:0,Aa:0,aa:0}; off.forEach(x=>n[x]++); const domN=n.AA+n.Aa;
   const ctx=`Em ${org}, ${dom} domina ${rec}. Cruzam-se indivíduos <b>${p1} × ${p2}</b>.`,tab=`Gametas: ${[...new Set(p1)].join(', ')} × ${[...new Set(p2)].join(', ')} → filhos: ${off.join(', ')}.`;
   if(t===0) return MC(`${ctx} Qual a probabilidade de um descendente ser <b>aa</b>?`,FR[n.aa],Object.values(FR).filter(x=>x!==FR[n.aa]),`${tab} aa aparece em ${n.aa} de 4: <b>${FR[n.aa]}</b>.`,'Monte o quadro de Punnett com os gametas de cada genitor.');
   if(t===1) return MC(`${ctx} Qual a porcentagem esperada de descendentes com o fenótipo <b>dominante</b>?`,PCT[domN],Object.values(PCT).filter(x=>x!==PCT[domN]),`${tab} Têm pelo menos um A: ${domN} de 4 = <b>${PCT[domN]}</b>.`,'Fenótipo dominante: AA ou Aa.');
   return MC(`${ctx} Qual a probabilidade de um descendente ser <b>heterozigoto (Aa)</b>?`,FR[n.Aa],Object.values(FR).filter(x=>x!==FR[n.Aa]),`${tab} Aa aparece em ${n.Aa} de 4: <b>${FR[n.Aa]}</b>.`,'Conte os Aa no quadro de Punnett.'); },
 sangue:lv=>{ const ok={O:['O'],A:['A','O'],B:['B','O'],AB:['AB','A','B','O']},all=['O','A','B','AB'];
   if(Math.random()<.6){ const r=pick(['O','A','B']),c=pick(ok[r]); return MC(`Considerando apenas o sistema ABO, uma pessoa do tipo <b>${r}</b> pode receber sangue de um doador do tipo:`,c,all.filter(x=>!ok[r].includes(x)),`Tipo ${r} pode receber de: <b>${ok[r].join(', ')}</b>. Não pode receber hemácias com aglutinogênio que ela não tem.`,'O receptor não pode receber aglutinogênio (A ou B) que não tenha.'); }
   const d=pick(['A','B','AB']),can=all.filter(r=>ok[r].includes(d)),no=all.filter(r=>!can.includes(r)); const c=pick(can);
   return MC(`Considerando apenas o sistema ABO, uma pessoa do tipo <b>${d}</b> pode doar sangue para alguém do tipo:`,c,no.concat(no.length<2?['nenhum tipo']:[]),`Tipo ${d} pode doar para: <b>${can.join(', ')}</b>.`,'O doador só pode dar para quem já tem o(s) mesmo(s) aglutinogênio(s).'); },
 piramide:lv=>{ const E=pick([10000,20000,50000,100000,5000]),k=R(2,4),v=E*0.1**(k-1),nm=['','produtores','consumidores primários','consumidores secundários','consumidores terciários'][k];
   return NUM(`Numa cadeia alimentar, os produtores fixam <b>${nf(E)} kcal</b>. Supondo que cada nível trófico aproveite cerca de 10% da energia do anterior, quanta energia chega aos <b>${nm}</b>?`,round(v,4),`A cada nível sobra ~10%: ${nf(E)} × 0,1<sup>${k-1}</sup> = <b>${nf(round(v,4))} kcal</b>.`,'Multiplique por 0,1 a cada passagem de nível trófico.',{unit:'kcal'}); }
};

