UNITS.push({id:'b3',title:'Evolução e diversidade',sub:'Teorias evolutivas, evidências, classificação, vírus, bactérias, protozoários e fungos',color:'#ff9600',dark:'#e07b00',skills:[
SKL('evolucao','Teorias da evolução','🦒','Lamarck: uso e desuso + herança de caracteres adquiridos (rejeitada). Darwin: seleção natural. Neodarwinismo: seleção natural + mutação + recombinação.',
`<ul><li><b>Lamarck</b>: <b>lei do uso e desuso</b> (órgãos usados se desenvolvem) e <b>herança dos caracteres adquiridos</b> — a segunda foi refutada.</li><li><b>Darwin</b> (<i>A Origem das Espécies</i>, 1859) e Wallace: <b>seleção natural</b> — há variação entre os indivíduos; os mais adaptados ao ambiente sobrevivem e deixam mais descendentes.</li><li><b>Neodarwinismo (teoria sintética)</b>: seleção natural + <b>mutação</b> e <b>recombinação gênica</b> como fontes de variabilidade.</li></ul>
<div class="ex">Girafas: para Lamarck, esticaram o pescoço e passaram isso aos filhos; para Darwin, as de pescoço mais longo já existiam, alcançavam mais alimento e deixavam mais descendentes.</div>
<h3>Evidências</h3><p><b>Fósseis</b>; <b>órgãos homólogos</b> (mesma origem, funções diferentes: braço humano e asa do morcego); <b>órgãos análogos</b> (mesma função, origens diferentes: asa de inseto e de ave); <b>órgãos vestigiais</b> (apêndice); semelhanças embrionárias e moleculares (DNA).</p>
<p><b>Especiação</b>: formação de novas espécies, geralmente após <b>isolamento geográfico</b> seguido de isolamento reprodutivo.</p>`,
{pairs:[['Lamarck','propôs a lei do uso e desuso e a herança dos caracteres adquiridos'],['Darwin','propôs a seleção natural em A Origem das Espécies (1859)'],['Neodarwinismo','une seleção natural, mutação e recombinação gênica'],['Órgãos homólogos','mesma origem embrionária, podendo ter funções diferentes'],['Órgãos análogos','mesma função, mas origens diferentes'],['Órgãos vestigiais','órgãos reduzidos e sem função evidente, como o apêndice'],['Especiação','formação de novas espécies, muitas vezes após isolamento geográfico']],
 qs:[['Bactérias resistentes a antibióticos aumentam quando o remédio é usado de forma errada porque:','o antibiótico seleciona as bactérias que já eram resistentes',['o antibiótico cria mutações de resistência de propósito','as bactérias "aprendem" a resistir e passam isso adiante','o antibiótico fortalece todas as bactérias'],'É <b>seleção natural</b>: as resistentes sobrevivem e se multiplicam.'],['A asa do morcego e o braço humano são órgãos:','homólogos',['análogos','vestigiais','idênticos'],'Mesma origem embrionária, funções diferentes.'],['A asa de uma borboleta e a asa de uma ave são órgãos:','análogos',['homólogos','vestigiais','rudimentares'],'Mesma função (voo), origens diferentes.'],['A ideia refutada pela genética de que "características adquiridas em vida são herdadas" é de:','Lamarck',['Darwin','Mendel','Wallace'],'Herança dos caracteres adquiridos: <b>Lamarck</b>.']]}),
SKL('classif','Classificação dos seres vivos','🗃️','Nomenclatura binomial (Lineu): gênero com maiúscula + espécie com minúscula, em itálico (Homo sapiens). Cinco reinos: Monera, Protista, Fungi, Plantae e Animalia.',
`<p><b>Lineu</b> criou a <b>nomenclatura binomial</b>: <i>Gênero espécie</i>, em latim, em itálico, gênero com inicial maiúscula (<i>Homo sapiens</i>, <i>Canis familiaris</i>).</p>
<p>Categorias: <b>reino → filo → classe → ordem → família → gênero → espécie</b>. Espécie: indivíduos que se cruzam e geram descendentes férteis.</p>
<table><tr><th>Reino</th><th>Características</th></tr><tr><td>Monera</td><td>procariontes (bactérias, cianobactérias)</td></tr><tr><td>Protista</td><td>eucariontes simples (protozoários e algas)</td></tr><tr><td>Fungi</td><td>eucariontes heterótrofos por absorção, parede de quitina (cogumelos, bolores, leveduras)</td></tr><tr><td>Plantae</td><td>eucariontes pluricelulares autótrofos (clorofila, parede de celulose)</td></tr><tr><td>Animalia</td><td>eucariontes pluricelulares heterótrofos por ingestão</td></tr></table>
<p>Hoje também se usam os três <b>domínios</b>: Bacteria, Archaea e Eukarya. A <b>cladística</b> agrupa os seres por ancestralidade comum.</p>`,
{pairs:[['Monera','reino dos procariontes, como bactérias e cianobactérias'],['Protista','reino dos protozoários e algas'],['Fungi','reino dos cogumelos, bolores e leveduras'],['Plantae','reino dos eucariontes pluricelulares autótrofos'],['Animalia','reino dos eucariontes pluricelulares heterótrofos por ingestão']],tq:t=>`O reino <b>${t}</b> reúne:`,dq:d=>`Qual reino corresponde a: <b>${d}</b>?`,
 qs:[['Qual é a forma correta de escrever o nome científico do ser humano?','<i>Homo sapiens</i>',['<i>Homo Sapiens</i>','<i>homo sapiens</i>','HOMO SAPIENS'],'Gênero com maiúscula, espécie com minúscula, em itálico.'],['A ordem correta das categorias, da mais ampla para a mais restrita, é:','reino, filo, classe, ordem, família, gênero, espécie',['espécie, gênero, família, ordem, classe, filo, reino','reino, classe, filo, família, ordem, gênero, espécie','filo, reino, classe, ordem, gênero, família, espécie'],'Reino → filo → classe → ordem → família → gênero → espécie.'],['O cavalo e o jumento geram a mula, que é estéril. Isso mostra que cavalo e jumento:','são de espécies diferentes',['são da mesma espécie','são do mesmo gênero e da mesma espécie','não têm parentesco'],'Espécie: cruzam e geram descendentes <b>férteis</b>.']]}),
SKL('micro','Vírus e bactérias','🦠','Vírus: acelulares, parasitas intracelulares obrigatórios, tratados com antivirais e prevenidos com vacinas. Bactérias: procariontes, combatidas com antibióticos.',
`<p><b>Vírus</b>: sem células, formados por material genético (DNA ou RNA) e cápsula de proteína. Só se reproduzem dentro de células. Antibióticos <b>não</b> funcionam contra vírus. Doenças: gripe, covid-19, dengue, zika, febre amarela, sarampo, AIDS (HIV), raiva, catapora.</p>
<p><b>Bactérias</b>: procariontes, com parede celular e, às vezes, plasmídeos. Muitas são benéficas (decomposição, fixação de nitrogênio, produção de iogurte, microbiota intestinal). Doenças: tuberculose, cólera, tétano, leptospirose, sífilis, hanseníase, meningite bacteriana. Tratamento: <b>antibióticos</b>.</p>`,
{pairs:[['Dengue','virose transmitida pelo mosquito Aedes aegypti'],['Tuberculose','doença bacteriana que afeta principalmente os pulmões'],['Cólera','doença bacteriana transmitida por água e alimentos contaminados'],['Tétano','doença bacteriana associada a ferimentos com objetos contaminados'],['Leptospirose','doença bacteriana transmitida pela urina de ratos'],['AIDS','síndrome causada pelo vírus HIV, que ataca células de defesa'],['Febre amarela','virose transmitida por mosquitos, prevenida por vacina'],['Sarampo','virose muito contagiosa, prevenida por vacina'],['Sífilis','infecção sexualmente transmissível causada por bactéria']],tq:t=>`Sobre a <b>${t}</b>, é correto afirmar que é:`,dq:d=>`Qual doença é <b>${d}</b>?`,
 qs:[['Por que antibióticos não curam a gripe?','porque a gripe é causada por vírus, e antibióticos agem sobre bactérias',['porque a gripe é causada por fungos','porque o vírus da gripe é uma bactéria resistente','porque antibióticos só funcionam em crianças'],'Antibióticos atuam em estruturas das <b>bactérias</b>.'],['Bactérias do gênero <i>Rhizobium</i>, nas raízes de leguminosas, são importantes porque:','fixam o nitrogênio do ar',['produzem oxigênio','causam doenças nas plantas','decompõem o solo'],'Fixação biológica do nitrogênio.'],['O principal meio de prevenir o sarampo e a febre amarela é:','a vacinação',['o uso de antibióticos','ferver a água','tomar antifúngicos'],'Ambas são viroses prevenidas por <b>vacina</b>.']]}),
SKL('protofungo','Protozoários, fungos e parasitoses','🐛','Malária: protozoário (Plasmodium), mosquito Anopheles. Doença de Chagas: Trypanosoma cruzi, barbeiro. Esquistossomose: verme Schistosoma, caramujo, penetra pela pele.',
`<p><b>Protozoários</b>: eucariontes unicelulares heterótrofos. Doenças: <b>malária</b> (<i>Plasmodium</i>, mosquito <i>Anopheles</i>), <b>doença de Chagas</b> (<i>Trypanosoma cruzi</i>, inseto barbeiro), <b>leishmaniose</b> (<i>Leishmania</i>, mosquito-palha), <b>amebíase</b> e <b>giardíase</b> (água e alimentos contaminados), toxoplasmose.</p>
<p><b>Fungos</b>: heterótrofos por absorção, parede de quitina; decompositores. Úteis: leveduras (pão, cerveja), <i>Penicillium</i> (penicilina), cogumelos comestíveis. Doenças: micoses, candidíase. Os <b>liquens</b> são associações de fungo + alga.</p>
<p><b>Vermes (helmintos)</b>: <b>esquistossomose</b> (<i>Schistosoma mansoni</i>; caramujo hospedeiro intermediário; larva penetra pela pele em água contaminada), <b>ascaridíase</b> (lombriga; ingestão de ovos), <b>teníase</b> (carne de porco ou boi mal cozida), <b>ancilostomose</b> (amarelão; larva penetra pela pele, andar descalço).</p>
<p>Prevenção geral: <b>saneamento básico</b>, água tratada, higiene dos alimentos, controle de vetores.</p>`,
{pairs:[['Malária','causada pelo protozoário Plasmodium e transmitida pelo mosquito Anopheles'],['Doença de Chagas','causada pelo Trypanosoma cruzi e transmitida pelo inseto barbeiro'],['Esquistossomose','verme que tem caramujo como hospedeiro intermediário e penetra pela pele'],['Ascaridíase','verminose da lombriga, adquirida pela ingestão de ovos'],['Teníase','verminose adquirida ao comer carne de porco ou boi mal cozida'],['Amarelão (ancilostomose)','verminose cuja larva penetra pela pele, comum em quem anda descalço'],['Leishmaniose','protozoose transmitida pelo mosquito-palha'],['Micose','infecção de pele causada por fungos']],tq:t=>`Sobre a <b>${t}</b>, é correto dizer que é:`,dq:d=>`Qual doença é <b>${d}</b>?`,
 qs:[['A penicilina, primeiro antibiótico, foi obtida a partir de:','um fungo (Penicillium)',['uma bactéria','um vírus','um protozoário'],'Alexander Fleming, 1928: fungo <i>Penicillium</i>.'],['Qual medida previne ao mesmo tempo esquistossomose, cólera e amebíase?','saneamento básico',['uso de repelente','vacina contra gripe','antibiótico preventivo'],'Todas ligadas a água e esgoto.'],['O líquen é uma associação entre:','fungo e alga (ou cianobactéria)',['bactéria e vírus','planta e animal','dois protozoários'],'Mutualismo fungo + alga.']]})
]});

