SKL('vert','Vertebrados','🐟','Peixes (brânquias), anfíbios (metamorfose, pele úmida), répteis (ovo com casca, escamas), aves (penas, endotérmicas) e mamíferos (pelos, glândulas mamárias).',
`<ul><li><b>Peixes</b>: respiram por brânquias; ectotérmicos; cartilaginosos (tubarão) ou ósseos.</li><li><b>Anfíbios</b> (sapos, rãs, salamandras): <b>metamorfose</b> (girino com brânquias → adulto com pulmões), pele fina e úmida (respiração cutânea); dependem da água para reproduzir.</li><li><b>Répteis</b> (cobras, lagartos, tartarugas, jacarés): pele com escamas de queratina e <b>ovo com casca</b> (amniótico) — conquista definitiva do ambiente terrestre; ectotérmicos.</li><li><b>Aves</b>: <b>penas</b>, bico sem dentes, ossos pneumáticos, sacos aéreos, <b>endotérmicas</b>.</li><li><b>Mamíferos</b>: <b>pelos</b> e <b>glândulas mamárias</b>, diafragma, endotérmicos; a maioria é placentária (monotremados, como o ornitorrinco, põem ovos).</li></ul>
<p><b>Ectotérmicos</b> dependem do ambiente para regular a temperatura; <b>endotérmicos</b> a mantêm constante (aves e mamíferos).</p>`,
{pairs:[['Peixes','vertebrados que respiram por brânquias'],['Anfíbios','vertebrados com metamorfose e pele úmida, como os sapos'],['Répteis','vertebrados com escamas e ovo com casca, como as cobras'],['Aves','vertebrados com penas e ossos pneumáticos'],['Mamíferos','vertebrados com pelos e glândulas mamárias'],['Endotérmicos','animais que mantêm a temperatura do corpo constante'],['Ornitorrinco','mamífero monotremado que põe ovos']],
 qs:[['O girino respira por brânquias e o sapo adulto, por pulmões e pela pele. Essa transformação é a:','metamorfose',['muda','regeneração','hibernação'],'Anfíbios passam por <b>metamorfose</b>.'],['A estrutura que permitiu aos répteis a reprodução longe da água foi:','o ovo com casca (amniótico)',['as brânquias','a pele úmida','a metamorfose'],'O ovo amniótico protege o embrião do ressecamento.'],['A baleia é um:','mamífero',['peixe','réptil','anfíbio'],'Tem glândulas mamárias e respira por pulmões.'],['São endotérmicos:','aves e mamíferos',['peixes e anfíbios','répteis e peixes','anfíbios e répteis'],'Mantêm a temperatura corporal constante.']]})
